INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (52, NULL, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Anton', 'mailingout@icloud.com', '39.144.141.43', 'Thank you for the detailed explanations.', 'approved', '2023-02-03 03:19:17');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (53, 52, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Chris Feichtner', 'cfe@me.com', '91.113.33.31', 'You''re welcome!', 'approved', '2023-02-03 06:59:35');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (54, NULL, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Anton', 'mailingout@icloud.com', '125.67.179.24', 'Hello Chris. Let me ask you some questions. Please tell me, what do you think about the fact that in the ProCamera (and any apps) app you only shoot RAW at 12 megapixels and ProRaw allows you to shoot at 48 megapixels? But ProRaw uses post-processing, and the results are unpredictable (although often good enough). So when you set ISO and shutter speed in ProRaw, you get an image with different exposure parameters. And don''t you get the feeling that there''s no point in shooting with ProRaw at manual settings?
Thanks in advance.', 'approved', '2023-02-12 11:01:20');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (55, 54, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Chris Feichtner', 'cfe@me.com', '104.28.130.6', 'Dear Anton,
Personally, I think there are a lot of scenarios, for which shooting with ProRAW and manual settings make sense. Though a ProRAW Photo runs through the photo pipeline, it still retains a lot of detail and information for manual post processing - compared to a compressed JPG or HEIF image. However, I do agree that it would be nice to be able to shoot a classic RAW with 48 megapixels.', 'approved', '2023-03-06 08:11:06');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (56, NULL, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Julie', 'julieharps@bigpond.com', '2001:8004:1d61:6a84:d460:61c9:34c4:617', 'Upgrading from an iPhone 8plus to an iPhone 14plus is quite a jump in photographic ability. I had no idea what RAW meant so I have been turning it off when taking photos. Also I have not chosen to use the noise reduction feature as there has not been background noise. 

Thank you for this informative explanation.', 'approved', '2023-03-02 21:24:22');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (57, 56, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Chris Feichtner', 'cfe@me.com', '104.28.130.6', 'You''re welcome, Julie.', 'approved', '2023-03-06 08:06:26');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (58, NULL, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Julie', 'julieharps@bigpond.com', '2001:8004:1d61:6a84:d460:61c9:34c4:617', 'Edit to previous post iPhone plus is iPhone pro', 'approved', '2023-03-02 21:25:48');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (59, NULL, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Linda Nicholls', 'lmnicholls@optonline.net', '69.112.224.51', 'Chris, I just bought an Apple iPhone 14 Pro specifically for the camera and this article is a godsend! 

I come from a casual SLR/DSLR background, but on my last trip noticed that my iphone 8 (8!) was shooting better pictures under certain conditions than my DSLR. I was and am ready to ditch the DSLR completely while traveling. 

But I had also seen my friend''s more advanced iPhone make unwanted and, to me, inappropriate "enhancements" that completely ruined the mood of the shot, most often by flooding it with excessive light. Your church photo here is a great example. I wanted to be able to override those auto-adjustments and create a photo that looked just the way I saw it in real life, and I knew RAW shooting and editing was the key, but I had no knowledge of how to use RAW on my phone. 

THANK YOU for taking the time to write this very detailed article.', 'approved', '2023-06-21 17:44:04');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (60, 59, '8aw3avirA-', 'https://nocamerabag.com/blog/how-to-shoot-raw-iphone', 'Chris Feichtner', 'cfe@me.com', '104.28.130.6', 'You''re welcome Linda! I''m happy my article was helpful and answered your questions.', 'approved', '2023-07-10 12:24:35');

