INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (75, NULL, 'lCOR14E2qD', 'https://nocamerabag.com/blog/live-photo-to-long-exposure', 'Toccata', 'imported@nocamerabag.com', '80.3.25.225', 'In reference to “ So, Apple has given us the possibility to adjust the exposure of a long exposure after we''ve taken it” - on my iPhone 15, trimming the Live Photo clip doesn’t seem to change the long exposure, it still seems to use the whole clip. Or am I doing something wrong', 'approved', '2025-07-04 17:56:43');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (76, 75, 'lCOR14E2qD', 'https://nocamerabag.com/blog/live-photo-to-long-exposure', 'Chris F.', 'cfe@me.com', '188.22.179.172', 'Most likely you''re not doing anything wrong. And in some cases editing the length of the clip does not have an effect; e.g. when "flattening" water in a lake. That typically happens in one second. Have you tried it on an object that moves fast?', 'approved', '2025-07-09 08:38:31');

