INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (106, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'osscafe', 'stuart.moore@srmoore.com', '2a00:23c5:318e:e01:b10a:8cbe:93b:464b', 'Are the functions in the app the same on iPad as iPhone? I have the ''Up'' subscription but the automatic perspective correction seems to be missing in capture and edit modes on iPad (all devices/apps are up to to date on iOS and app version). Thanks.', 'approved', '2023-04-03 08:09:20');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
