INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (109, 108, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Chris Feichtner', 'cfe@me.com', '104.28.130.6', 'The app offers ways to do so. The first one is to turn off HDR. The second option, which would require additional processing ist, to take photos in RAW format.', 'approved', '2023-07-19 12:26:21');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (110, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Rob W', 'imported@nocamerabag.com', '24.218.35.224', 'Thx for a very informative site. You’ve convinced me to try all this for myself, including ProCamera and the Up! subscription. As a LR user, I’m scratching my head as to best workflow for RAW images taken using ProCamera’s APC …the APC adjustment is “lost” on import of the RAW file to LR. Do you only use APC with HEIC images or am I missing something obvious?', 'approved', '2023-10-27 12:10:11');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (111, 110, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Chris F.', 'cfe@me.com', '194.166.144.190', 'Hi Rob,
you''re right - it''s lost because it''s not saved in the RAW file, rather than in a separate file (otherwise it wouldn''t be a RAW anymore). Yes, if I use APC, i save it as a HEIC and import and edit that in Lightroom.', 'approved', '2023-11-03 15:18:05');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (112, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Kevin Shipman', 'sierrakevin@gmail.com', '12.105.135.226', 'I use ProCamera for video and I like the ability to zoom while recording through the entire range. But there are hitches as the lenses change. Is there any fix for that? Also, how will the app work with the new extended zoom capability of the iPhone 15 Pro Max? Thank you in advance.', 'approved', '2023-10-31 20:59:12');

