INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (114, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Calvin woodings', 'Cw@nonwoven.co.uk', '2a00:23c6:3c8d:5601:b1a8:4a14:8a56:3e9f', 'A really helpful and comprehensive review! I don’t do video either, but would be interested in your comments on how it works with the new features on the iPhone 15 Pro Max before I buy one.', 'approved', '2023-12-06 20:01:29');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (115, 114, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Chris F.', 'cfe@me.com', '91.113.33.68', 'Dear Clavin, thanks! I''m happy you found the review helpful. I can confirm that all the photo features work on the iPhone 15 Pro Max - but I can''t tell anything about the video features as I don''t use them.', 'approved', '2023-12-12 09:19:37');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (116, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Pascal', 'forpascal@hotmail.com', '2a02:8429:a0b4:8e01:c176:1776:ac28:7b52', 'I am still unsure about the ProCamera app. I find that the pictures I get are much colder than the ones taken by the native app...
Is this just a setting to change?
