INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (117, 116, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Chris F.', 'cfe@me.com', '188.22.182.152', 'Hi Pascal,

If they look cooler ..., how did you take them? In RAW format? in ProRAW format? Or just in JPEG? The best image quality generally is the RAW format, but you''d need to edit the photos afterwards.', 'approved', '2025-02-24 08:34:26');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (118, 117, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Pascal', 'forpascal@hotmail.com', '2a02:8429:a0b4:8e01:c8c4:92d1:b7ab:4996', 'hi, Chris, thanks for your reply, I usually take my pictures both in the iPhone camera app and the ProCamera app in HEIF format. What is surprising is that when I take pictures with the iPhone camera app and the same picture with the ProCamera app the size of the ProCamera app picture is three times bigger than the one I obtain using the native iPhone camera app. Why is that?

On another note, I usually take all my pictures in the format 2:1. I did set the parameters to keep on the edited version both versions 2:1 but also 4:3. When I want to edit my photos after taking them if I go to the ProCamera app editing device. I can still recover what was part of the 4.3 picture, but I cannot do it in the native editing tool of my iPhone (in this case I can only see the 2:1 picture and no possibility to reframe outside of this format). Nevertheless, if I take the same picture with the iPhone native app, in that case, I can recrop and recover the 4:3 part of the image. To complete my comment, the image I took with the ProCamera app at 2:1 if I edit it with the ProCamera app, yes in that case I can recover the 4:3 part of the picture. Just strange to see that the iPhone editing tool does not understand that the 4:3 part of the image exist if it has been taken bi the ProCamera app...', 'approved', '2025-02-24 09:30:23');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (119, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Jim', 'springhopephotographer@gmail.com', '2603:6080:1e08:bcd:4035:6260:4ce2:e215', 'Hey Man!
Great job on this writeup. I run a stack of now vintage Nikon DSLR''s (y2000-2010 all models, d40x - d700), but having a 14pro in my pocket, knowing it was much more powerful as an actual cam than I was taking advantage of, was killing me.
I started researching apps to get more out of the phone''s camera and lenses, and came across your piece here.
I was leaning toward this app, but your writeup convinced me.
I hated to drop $30 US on an app (I really did hate that part), but I went for it and I''ve been playing with it for just an hour or two and HOLY CRAP!
You were right. THIS APP IS AMAZING.
Now I have another camera, and as we say, this one is always with me.
Much appreciated, good work.
-Jim, USA', 'approved', '2025-04-06 04:22:54');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (120, 119, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Chris F.', 'cfe@me.com', '188.22.178.70', 'Hi Jim and thanks for taking the time to let me know that my post helped you to decide. That''s exactly why I''m running this blog for more than 12 years!', 'approved', '2025-04-06 15:06:04');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (121, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Davide', 'pindavide@gmail.com', '92.223.214.250', 'Hi Chris, congratulations on the great work done. I would like to ask you if with ProCamera you can have depth of field control even when shooting in raw. In iPhone the depth of field control exists only in portrait mode (iPhone 15 Pro in my case) and it only shoots in 3mb jpeg which if printed become a disaster. Does ProCamera allow you to do the same "game" in post-production even when shooting in raw / proraw? thanks', 'approved', '2025-04-30 09:33:34');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (122, 121, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Chris F.', 'cfe@me.com', '188.22.170.77', 'As of May 2025, all "Depth of Field" functions in all camera apps are based on AI (like Portrait Mode). The reason is, that the iPhone camera hardware has a fixed aperture. Unfortunately, there''s no way you can adjust the aperture and thus depth of field in any camera app directly. The only two ways I use to apply (AI based) depth of field is Portrait Mode and the background blur function in Lightroom Mobile (independently of the camera app you use).', 'approved', '2025-05-05 07:13:41');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (123, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Tracy', 'vacant54swats@icloud.com', '2a09:bac3:5b2b:1955::286:90', 'Great article. I continue to return to it for reference as I learn the app. One question though … even tapping the lens selection as you mention … I cannot get ProCamera to select the 2x optical lens on iPhone 16Pro. Just returned from a trip to Iceland and I had to repeatedly revert to the native iPhone camera app to utilize the 2x lens. 😔
Any suggestions? Thanks in advance…', 'approved', '2025-09-02 16:26:53');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (124, 123, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'Chris F.', 'cfe@me.com', '188.22.175.30', 'Puh, that''s difficult. I can just say that it works on my phone. Unfortunately, I can''t help you much with your question. Have you contacted the app support?', 'approved', '2025-10-05 19:00:11');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (125, NULL, 'V1CtS-MvlE', 'https://nocamerabag.com/blog/procamera-app-review', 'John Wehlitz', 'John.wehlitz@gmail.com', '2a02:26f7:c34c:81d0:0:e000:0:e', 'Thanks for an interesting article. When I go to 2X zoom, although the 48 mp indicator remains on, when I check the resolution of the resulting photo, it’s actually 12 mp. I’m using an iPhone 16 Plus, so I wonder if it would really be 48 mp with a pro model phone.', 'approved', '2025-11-28 02:21:02');

