INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (126, NULL, 'PEj97oFr6p', 'https://nocamerabag.com/blog/raw-workflow-lightroom-mobile', 'John', 'imported@nocamerabag.com', '67.169.210.246', 'Thanks for this description of your workflow. This will help me return to a too-long dormant iPhone Lightroom project I started last year. Meanwhile, I''m curious about one item you didn''t cover: if someone downloads one of your images, does it come down as a RAW file, or as a JPEG (or something else)?

The reason I ask: I''ve just used Lightroom (not Classic, not Mobile, since I''m using a Canon 5DM3 shooting RAW+JPG) for the first time for a client project.

After shooting, I imported only the RAW files to Lightroom on my Mac using the app, not the web interface; color balanced etc.; uploaded final results to my Adobe CC online galleries; shared them to the client – then found that they could only download big JPGs, not RAWs.

I think I''m missing something, but I''m not positive what. Does Lightroom convert processed RAW files to JPGs before uploading to web galleries? Or does it convert online RAW files to JPGs when downloaded? Or does it only allow RAW downloads for Adobe CC members, and JPGs for non-members?

Anything you know on this topic would be appreciated.

Keep up your good work!', 'approved', '2022-04-08 18:52:23');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (127, NULL, 'PEj97oFr6p', 'https://nocamerabag.com/blog/raw-workflow-lightroom-mobile', 'Juul', 'imported@nocamerabag.com', '84.243.240.106', 'I’ve made adjustments on some ProRaw files, straight out of my photo album, not in Lightroom. I want to make some final local adjustments in Lightroom, but when I import the edited ProRaw file into Lightroom, the adjustments I made earlier aren’t there. Is it possible to import a ProRaw file into Lightroom, including earlier made adjustments?', 'approved', '2022-10-06 09:07:46');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (128, 127, 'PEj97oFr6p', 'https://nocamerabag.com/blog/raw-workflow-lightroom-mobile', 'Chris Feichtner', 'cfe@me.com', '213.162.73.142', 'Hi, unfortunately, that‘s not possible due to the way edits to RAW files hare handled. The edits are not directly applied to the RAW photo rather than saved as „editing steps“ (Otherwise, the edited photo wouldn‘t be a RAW file any more). Lightroom can‘t read (or does not understand) the edit steps made in Photos App; thus you‘ll have to start from scratch when you import a file into Lightroom. Hope this helps.', 'approved', '2022-10-06 11:00:37');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (129, NULL, 'PEj97oFr6p', 'https://nocamerabag.com/blog/raw-workflow-lightroom-mobile', 'RAbbott', 'rvabbott25@gmail.com', '70.21.15.180', 'I usually shoot raw on my “real camera” but have never done so on an iPhone. How do you manage your files? Do you shoe raw for all iPhone pictures or only some? What happens if you want to text a picture? Is there a way to convert from raw to HEIC — which takes up less room than JPEG? Finally, how do you backup images and get them off the phone? One advantage of shooting HEIC is that the photos automatically get saved to iCloud. Does that occur if you shoot raw?', 'approved', '2022-10-23 03:15:31');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (130, 129, 'PEj97oFr6p', 'https://nocamerabag.com/blog/raw-workflow-lightroom-mobile', 'Chris Feichtner', 'cfe@me.com', '62.178.50.2', 'That’s a lot of valid questions! I’ll take them and update my blogpost in the next few weeks.', 'approved', '2022-10-30 19:21:30');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (131, NULL, 'PEj97oFr6p', 'https://nocamerabag.com/blog/raw-workflow-lightroom-mobile', 'shahar', 'checkmate9@gmail.com', '213.57.224.206', 'hi, i have creative cloud subscription and iphone setting for proraw, but I don''t see this profile, just "color" profile', 'approved', '2023-03-02 04:31:17');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (132, 131, 'PEj97oFr6p', 'https://nocamerabag.com/blog/raw-workflow-lightroom-mobile', 'Chris Feichtner', 'cfe@me.com', '89.144.199.149', 'From your answer, I suppose you looked under „Presets“. You’ll find it under Profiles.', 'approved', '2023-03-06 18:52:37');

