INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (133, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Andy', 'andyc.maciver@gmail.com', '142.116.98.143', 'I’m amazed no one has thanked you for this blog. I’m new to iPhone photography. I’ve read many reviews of the popular camera apps. When I note what Apple’s own camera/photo apps can do, I then ask myself what else do I need? I think you have done a great job narrowing down the field. I’m still not sure I even need a ProCamera type of app. Initially I thought definitely because I want control of the shutter speed and that 48mb jog. Maybe I still do but I wonder if that is just old school mentality. The hi speed burst mode may be all I need for capturing the moment. And how many high detail shots do I really need? 

Keep up these excellent and concise posts.', 'approved', '2023-09-30 20:53:35');

