INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (146, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Michelle', 'spyral@aol.com', '93.146.68.76', 'Thanks for this post! I teach a summer photography course and Camera+ Pro is no longer affordable for my students. Though I prefer the convenience of having many of these features in one app, Slow Shutter Cam and ProCamera are super easy to use and way more affordable.', 'approved', '2024-07-01 18:20:18');

