INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (148, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Luca', 'luca.dellepiane.1965@gmail.com', '93.36.110.152', 'Thank you for this review. I would like to try using the iPhone for night sky shooting, for this reason I need long exposure times, seconds up to minutes for my auto-tracking system, and RAW format for PC post processing, combined in a single app. Does ProCamera include a B mode?', 'approved', '2024-07-11 12:12:02');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (149, 148, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Chris F.', 'cfe@me.com', '80.121.44.11', 'Hi Luca, unfortunately, as the shutter speed of the iPhone is limited by hardware (to my best knowledge to 1 second) you''ll need a camera app simulating a long exposure (like slow Shutter Cam App).', 'approved', '2024-08-26 12:54:32');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (150, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Kenneth', 'imported@nocamerabag.com', '223.17.149.66', 'Can ProCamera support shutter speed longer than 10sec ? As i want to control it for taking milky way. Thanks', 'approved', '2024-07-13 10:26:20');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (151, 150, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Chris F.', 'cfe@me.com', '80.121.44.11', 'Unfortunately, no. The shutter speed of iPhone is limited by hardware (to the best of my knowledge, it''s 1 second). For longer shutter speeds, you need to turn to a dedicated long exposure camera app. They will simulate a longer shutter speed by capturing multiple images or even a video and then calculate a final image (emulating a longer shutter speed).', 'approved', '2024-08-26 12:52:15');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (152, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Paul', 'paul@paul-brown.com', '119.18.1.49', 'Hi - thanks you for this valuable information. I''m wondering if you can help me - I''m looking for a camera app (still frame) that allows variable shutter speed. I use ProMovie for video recording and it allows this facility - I can set 1/75 second for recording off old crt monitors without bars. The camera apps I have found so far only allow fixed speeds - 1/30, 1/60, 1/80, etc... Do you know of anything that will enable a continuous variable shutter speed? Than you in advance. Paul', 'approved', '2024-08-23 22:11:56');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (153, 152, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Chris F.', 'cfe@me.com', '80.121.44.11', 'Hi Paul,

thanks for your comment. The problem with "variable" shutter speed ist, that the shutter speed of the iPhone is limited by hardware (to the best of my knowledge to 1 second). If that is enough for you, you can use e.g. ProCamera App which allows you to set the shutter speed manually (with a max of 1 second). If you need a longer exposure, you have to turn to one of the long shutter camera apps. But as the shutter speed is limited by hardware, these long exposure apps basically capture multiple images or even a video and calculate a long exposure from that. So essentially, they''re simulating a longer shutter speed (that you can set freely).', 'approved', '2024-08-26 12:50:22');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (154, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Anais Harris', 'harrisanaisuk@gmail.com', '2a02:c7c:f2bf:3b00:41e0:5b2e:cf9a:7c97', 'Hi,
Thank you for this it is really helpful! I mostly take theatre photography so musicals etc where the lighting is tricky and people are moving around. What would you recommend I use for that? I need clear good quality photos of the performers. For reference I have an iPhone 16 pro max.
Thanks!', 'approved', '2024-10-24 18:24:15');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (155, 154, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Chris F.', 'cfe@me.com', '89.144.214.254', 'Hi,

That’s tricky with iPhone, even with an iPhone 16. You need good light. Then I’d give ProCamera App a try as you can manually set the exposure time and ISO. You may want to try priority mode, setting the shutter speed as fast as possible. I’d also shoot in RAW, so you can brighten the image.', 'approved', '2024-10-25 08:13:57');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (156, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Derek', 'graphicartdude@gmail.com', '2a09:bac3:7d58:1973::289:58', 'Great article. I figured I’d chime in about the 1 second shutter speed limitation mentioned. I also thought this to be the case, however when shooting a night sky I discovered I was able to achieve upwards of 30 second exposures on my iPhone 15 Pro, using only the default Camera app.

To do this set your Camera app to ‘photo’… then make sure the moon/sun icon is enabled (upper left of camera app screen) & the ‘Raw Max’ icon is enabled (upper right of camera app screen). By default the shutter speed is 1-3 seconds, though if your environment is dark enough & requires more light, the camera app will automatically increase the exposure time (up to 30 seconds). 

But this only works if your phone is completely still (using a tripod or resting against a stationary object/surface). The minute the phone senses motion, the longer exposure time will revert back to a shorter one. When shooting the northern lights my phone would fluctuate between 10 & 40 second exposures, depending on how much ambient light there was. 

Hope this helps.', 'approved', '2024-12-04 01:44:12');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (157, 156, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Chris F.', 'cfe@me.com', '62.47.241.188', 'Hi Derek, you''re right. But the iPhone Camera App basically does the same thing as Slow Shutter Cam App does (it''s not "hardware" long exposure). However, Slow Shutter Cam App gives you a bit more control like ISO-Setting and bulb mode. That''s why I recommend it (over the built in night mode).', 'approved', '2025-01-14 08:57:57');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (158, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'phaul2001', 'pdl@delaego.net', '217.254.82.32', 'Hello, thank you for this very helpful blog. Before reeHeld I used Spectre (from the Halide guys) what has more or less the same functionality. But I find the results of reeHeld of better quality.

BR Thomas', 'approved', '2025-01-13 18:04:40');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (159, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Wankja Ferguson', 'info@vlindererbij.nl', '2001:1c01:4280:c100:54e7:2a19:4b3e:40c1', 'Which app would be the best to get more optical zoom (IPhone 16 pro Max )', 'approved', '2025-01-19 09:57:49');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (160, 159, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Chris F.', 'cfe@me.com', '62.47.241.188', 'No app will bring you more optical zoom. The optical zoom is a built-in hardware. To get more optical zoom, you''ll need to use a third-party zoom lens like the one from Sandmarc.', 'approved', '2025-01-19 19:52:12');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (161, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Abe', 'Avimemka@gmaill.com', '2001:861:e3d5:fb80:a512:eae8:fcfa:2669', 'An alternative to reelheld is spectre ; it works handheld and uses AI too', 'approved', '2025-01-28 06:48:13');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (162, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Jim Wayda', 'jim@wayda.com', '47.145.184.147', 'Thank you for an excellent article. I am hoping that you can shed some light on my problem. I use Photomatix for HDR processing and therefore I prefer to shoot HDR images by using AEB with 3, 5, or 7 shots. On a real DSLR, you set the aperture, ISO, and the middle shutter speed. The DSLR then shoots the bracket by varying the shutter speed. This is the correct way to shoot a bracket. The problem is that after market camera apps for the iPhone shoot brackets differently. They vary both the ISO and the shutter speed. When I go to process these brackets in Photomatix, the software complains and indicates that substandard results should be expected because the ISO is varying and needs to be held constant. I have discussed this with the creators Photomatix and they confirmed that the ISO needs to be held constant when shooting brackets. I have asked the creators of ProCamera to make this simple change, but can’t get them to commit to implementing it. I also tested the Moment Camera app and it also varies the ISO. Are you aware of any iPhone camera apps that can shoot brackets correctly like a DSLR by holding the ISO constant and only varying the shutter speed?

Thanks,
-jim', 'approved', '2025-02-01 04:24:40');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (163, 162, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Chris F.', 'cfe@me.com', '188.22.182.152', 'Hi Jim,

the Problem is the iPhone hardware. The shutter speed is limited to 1 second, and thus all camera apps use a different way (ISO) to produce the different exposures. I''m not aware of any camera app that uses the shutter speed like you mentioned.

Back in my good old days we used to take bracketed shots by varying the aperture.', 'approved', '2025-02-03 09:37:12');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (164, NULL, 'BxR3RG7B1P', 'https://nocamerabag.com/blog/recommended-camera-apps', 'Adam', 'imported@nocamerabag.com', '119.155.185.22', 'Thank You for this helping article. I will share my personal experience with you soon.', 'approved', '2025-04-21 16:29:34');

