INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (186, NULL, 'g2YuGPu-GF', 'https://nocamerabag.com/blog/review-adobe-lightroom-mobile-premium', 'Martin', 'Martinboxman1875@gmail.com', '104.243.223.29', 'Many Thanks for this comprehensive review , composed in an understandable format for novices like me. I would like to download the initial free mobile L/Rm but I cannot find a way to do this, even though I have created a creative cloud account, ( to use photoshop express ).. I am very low tech bu I just cannot locate where or how to download the mobile L/Rm app. Any advice would be most appreciated. Best wishes.', 'approved', '2023-11-22 18:33:49');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (187, 186, 'g2YuGPu-GF', 'https://nocamerabag.com/blog/review-adobe-lightroom-mobile-premium', 'Chris F.', 'cfe@me.com', '194.166.144.190', 'Hi Martin, I''m gald you found the review helpful. You should be able to download Lightroom Mobile from the app store directly on your mobile.', 'approved', '2023-11-24 23:06:43');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (188, NULL, 'g2YuGPu-GF', 'https://nocamerabag.com/blog/review-adobe-lightroom-mobile-premium', 'Jason', 'jkriishka1@gail.com', '2604:3d09:a780:370:396d:262a:efb7:dd7e', 'Great review! I’m looking to free up space in my iPhone. Does the paid mobile version of Lightroom automatically save all its photos to their cloud? And how much space does Lightroom still take up on your phone?', 'approved', '2024-06-01 13:35:40');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (189, 188, 'g2YuGPu-GF', 'https://nocamerabag.com/blog/review-adobe-lightroom-mobile-premium', 'Chris F.', 'cfe@me.com', '80.121.44.11', 'Hi and yes, Lightroom saves all to the creative cloud but also syncs it to your device. The size of Lightroom depends on how much photos are synced to the device.', 'approved', '2024-08-26 12:56:01');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (190, NULL, 'g2YuGPu-GF', 'https://nocamerabag.com/blog/review-adobe-lightroom-mobile-premium', 'Eliza Thulson', 'elizathulson@gmail.com', '165.225.11.49', 'Hi! Great review. I have lightroom premium purchased via subscription on my iPhone. I can''t figure out how to log in to the premium account on my ipad - it keeps prompting me to purchase a new subscription. Do you have any tips? Thank you!', 'approved', '2024-09-13 16:41:30');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (191, 190, 'g2YuGPu-GF', 'https://nocamerabag.com/blog/review-adobe-lightroom-mobile-premium', 'Chris F.', 'cfe@me.com', '62.47.241.239', 'Hi Eliza,

thanks for your kind words. How did you purchase the subscription? Via Adobe or via Apple Store? Make sure you''re signed in to Lightroom using the same E-Mail. If that doesn''t work, I''m sure the Adobe support is happy to help.', 'approved', '2024-09-17 21:40:30');

