-- -----------------------------------------------------------------------------
-- Post: Review of the Neewer iPhone cage. It’s a versatile rig for photography
-- Page ID: HKxtsDKjN- | Page URL: https://nocamerabag.com/blog/review-neewer-iphone-cage
-- Comments count: 4
-- -----------------------------------------------------------------------------
INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (211, NULL, 'HKxtsDKjN-', 'https://nocamerabag.com/blog/review-neewer-iphone-cage', 'Joel', 'imported@nocamerabag.com', '24.144.37.199', 'Did you feel this was more helpful for videography or photography? Or the same?', 'approved', '2025-06-18 14:00:29');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (212, 211, 'HKxtsDKjN-', 'https://nocamerabag.com/blog/review-neewer-iphone-cage', 'Chris F.', 'cfe@me.com', '188.22.179.172', 'Hi Joel, as I only use it for photography, I can''t compare it to videography. But for photography, it''s definitely helpful. Mainly for the option to add one (or two) grips and to attach it directly to a tripod without the need for any extra accessories.', 'approved', '2025-06-20 11:33:59');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (213, NULL, 'HKxtsDKjN-', 'https://nocamerabag.com/blog/review-neewer-iphone-cage', 'Artur', 'arturtajber@gmail.com', '2a02:26f7:c949:4000:c000::22', 'I use this cage as well, with the difference in that I mainly film with the iphone, I only take photos with it when I don''t have a bigger camera to hand. My first video camera is a Sony FX3, but it''s difficult to have it with all the gear always at hand. The cage helps a lot with filming, perhaps even more than with shooting. If we do not want to use a stabiliser with a mechanical gimbal, the sheer increase in surface area and weight of the device helps to control movement and horizon stabilisation. The cage protects not only the phone but also - thanks to the larger edge profile - the external SSD if it is used during filming. Attaching the handles further increases the control.', 'approved', '2025-08-03 11:05:09');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (214, 213, 'HKxtsDKjN-', 'https://nocamerabag.com/blog/review-neewer-iphone-cage', 'Chris F.', 'cfe@me.com', '194.166.239.99', 'Thanks for your valuable comment about using the case when filming, which I couldn''t cover as a photographer.', 'approved', '2025-08-03 15:34:01');

-- -----------------------------------------------------------------------------
-- Post: Photomator App review and why I switched to it from Lightroom Mobile
-- Page ID: clEBgYtW1K | Page URL: https://nocamerabag.com/blog/review-photomator
-- Comments count: 8
-- -----------------------------------------------------------------------------
INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (215, NULL, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'BAkkel', 'koolmees.tegens.0c@icloud.com', '143.178.53.120', 'I''m planning to switch as well, but I''m looking for a way to transfer all my photos into Pixelmator, including the settings and adjustments. Anny suggestions?', 'approved', '2025-07-08 06:31:14');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (216, 215, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'Chris F.', 'cfe@me.com', '188.22.179.172', 'Not really. There is no way I now of to import the edits into Photomator. You can export and convert edits to LUTs, but this way you''ll end up with 100 or 100s of LUTs. What I did was to export all the final edits to a hard drive. Then I created presets in Photomator from my custom presets in Lightroom and began to re-edit my photos by relevance.', 'approved', '2025-07-09 08:36:39');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (217, NULL, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'Joseph', 'Josneyens5@gmail.com', '2a02:1810:9529:af00:4d8e:5cca:5825:a976', 'Blijf je met een Lifetime aankoop ook je updates behouden?', 'approved', '2025-07-28 17:59:28');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (218, 217, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'Chris F.', 'cfe@me.com', '194.166.239.99', 'Dear Joseph, I''m happy to answer your question in English: I don''t know exactly, but I believe the minor version updates (e.g. 2.x) yes. I don''t know about the major version updates, e.g. vom 2 -> 3.', 'approved', '2025-07-30 06:50:42');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (219, NULL, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'David', 'bellamydm@gmail.com', '2601:640:8a01:dac0:849f:e3dd:c8c0:b591', 'Great summary, thank you. I’m in the process of switching from Lightroom too. Curious if you have found a workaround for the lack of a dehaze function?', 'approved', '2025-08-18 15:32:31');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (220, 219, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'Chris F.', 'cfe@me.com', '194.166.239.39', 'You''re welcome. I haven''t found an exact replacement, but I''m currently using masks and a combination of contrast, (selective) clarity, and highlights to "simulate" the missing dehaze function. I hope this helps.', 'approved', '2025-08-28 13:51:17');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (221, NULL, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'Martin', 'martin@yetic.net', '2a09:bac3:1bae:2be::46:b7', 'Hi. Photomator is a good app. I have used it. Lack of lens correction is what made me give up on it to edit RAW files. However the main issue is that Apple bought the company almost a year ago, and have yet to announce what the future of the app may be, if there is any future. For now the app remained unchanged for a year and there is no sign of development. One could hope something would happen along the release of v26 version of apple OS''s, but nothing. So maybe Apple is working on something and the app has a future. Nothing is certain, that is for sure.', 'approved', '2025-09-26 16:01:13');

INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (222, 221, 'clEBgYtW1K', 'https://nocamerabag.com/blog/review-photomator', 'Chris F.', 'cfe@me.com', '188.22.175.30', 'I see your point, Martin. I''m also curious to see, how the app evolves. If it doesn''t, there are many other alternatives to try. I''ll keep you informed here in my blog.', 'approved', '2025-10-05 18:58:54');

