-- Comments count: 1
-- -----------------------------------------------------------------------------
INSERT INTO comments (id, parent_id, page_id, page_url, author_name, author_email, author_ip, content, status, created_at)
VALUES (232, NULL, '_yV2a-X_Ng', 'https://nocamerabag.com/blog/review-skrwt-app', 'Yifu', 'yifu066@gmail.com', '130.88.226.14', 'Hi Chris,
This is a very good review. I also enjoy using SKRWT. However, I noticed a dramatic downgrade in image quality when I imported my photo (format: JPEG or HEIC. I am using Fujifilm X-T50). The image would become super blurry. After exporting, I checked the metadata in the photo app, and the megapixels weren''t changed.
It also happens when I import photos shot by iPhone. However, this weird phenomenon goes away if I use the other two functions.
Have you experienced the same recently? If so, any ideas how to fix it? This app has no alternative in my currently workflow and it''s really a pain in the ass.', 'approved', '2025-12-01 18:23:25');

